<template>
  <div
    class="inbox-item"
    :class="{ 'inbox-item--resolved': item.status !== 'pending' }"
  >
    <!-- Header -->
    <div class="inbox-item__header">
      <q-avatar color="orange-7" text-color="white" size="24px" font-size="12px" class="q-mr-sm flex-shrink-0">
        <q-icon name="front_hand" />
      </q-avatar>
      <div class="inbox-item__content col min-width-0">
        <div class="inbox-item__title ellipsis">{{ item.title }}</div>
        <div class="inbox-item__subtitle row items-center no-wrap q-gutter-xs">
          <AssigneeChip
            v-if="item.agent_name"
            :name="item.agent_name"
            type="agent"
            size="sm"
          />
          <span v-else>{{ item.requested_by_name }}</span>
          <span class="inbox-item__time">&middot; {{ formatTime(item.created_on) }}</span>
        </div>
      </div>
      <q-btn
        v-if="item.mission_id && !hideMissionLink"
        outline dense no-caps
        color="primary"
        icon="arrow_forward"
        :label="$t('open_mission')"
        size="sm"
        class="q-ml-sm flex-shrink-0"
        @click.stop="$emit('select', item.id)"
      />
      <span v-if="item.status !== 'pending'" class="text-caption text-grey-6 q-ml-sm flex-shrink-0">
        {{ statusLabel($t, item.status) }}
      </span>
    </div>

    <!-- Action panel (pending only) -->
    <div v-if="item.status === 'pending'" class="inbox-item__body">
      <!-- Context / description -->
      <div v-if="item.description" class="inbox-item__description markdown-body q-mb-xs" v-html="renderMarkdown(item.description)" />

      <!-- Approve / Reject buttons.
           Disabled while a message is drafted so the three actions
           stay visually disjoint — Approve/Reject are bare quick
           decisions (no note flows to the agent), Send (below) is
           the redirect-with-explanation path that uses the typed
           message.  ``FellowButton`` exposes ``blocked`` (not
           ``disable``); using ``:disable`` here would silently
           no-op since it isn't a declared prop. -->
      <div v-if="hasProposalOptions" class="row no-wrap q-gutter-xs q-mb-xs">
        <f-btn
          v-for="opt in proposalOptions"
          :key="opt.action"
          :appearance="opt.action === 'approve' ? 'positive' : opt.action === 'reject' ? 'negative' : 'secondary'"
          :label="opt.label"
          :icon="opt.action === 'approve' ? 'check' : opt.action === 'reject' ? 'close' : undefined"
          size="sm"
          :blocked="hasMessageDraft"
          :loading="acting && pendingAction === opt.action"
          class="col"
          @click="quickAction(opt.action)"
        />
      </div>

      <!-- Message input -->
      <div v-if="item.mission_id" class="row no-wrap q-gutter-xs message-input-row">
        <q-input
          v-model="resolutionNote"
          dense
          outlined
          autogrow
          :placeholder="hasProposalOptions ? $t('alternative_instructions_optional') : $t('message_to_agent')"
          input-style="font-size: 0.78rem"
          class="col"
          @keyup.ctrl.enter="quickAction('comment')"
        />
        <f-btn
          appearance="primary"
          :label="$t('send')"
          icon="send"
          :blocked="!resolutionNote.trim()"
          :loading="acting && pendingAction === 'comment'"
          class="send-btn"
          @click="quickAction('comment')"
        />
      </div>
    </div>

    <!-- Resolved: show resolution note -->
    <div v-if="item.status === 'resolved' && item.resolution_notes" class="inbox-item__resolution-note">
      <q-icon name="notes" size="12px" color="grey-6" class="q-mr-xs" />
      {{ item.resolution_notes }}
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetInboxItem } from 'src/@types/docnet';
import { renderMarkdown } from 'src/utils/markdown';
import { formatRelativeTime } from 'src/utils/docnet/formatting';
import AssigneeChip from './AssigneeChip.vue';
import { inboxActionLabel, statusLabel } from './docnet-labels';

export default defineComponent({
  name: 'InboxDropdownItem',
  components: { AssigneeChip },

  props: {
    item: {
      type: Object as PropType<DocNetInboxItem>,
      required: true,
    },
    hideMissionLink: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['act', 'dismiss', 'select'],

  data() {
    return {
      acting: false,
      resolutionNote: '',
      pendingAction: null as string | null,
    };
  },

  computed: {
    proposalOptions(): Array<{ label: string; action: string }> {
      if (!this.item.available_options?.length) return [];
      return this.item.available_options
        .filter((o: any) => o.action && o.label)
        .map((o: any) => ({
          action: o.action,
          label: inboxActionLabel(this.$t, o.action, o.label),
        }));
    },

    hasProposalOptions(): boolean {
      return this.proposalOptions.length > 0;
    },
    /** True when the user has typed something into the message input.
     *  Used to disable Approve/Reject so the three actions stay
     *  disjoint: typing implies the user wants the redirect (Send /
     *  ``comment``) path, not a bare approve/reject. */
    hasMessageDraft(): boolean {
      return !!this.resolutionNote.trim();
    },
  },

  methods: {
    renderMarkdown,
    statusLabel,

    quickAction(action: string) {
      this.pendingAction = action;
      this.acting = true;
      // Three actions, three semantics:
      //   * approve / reject — bare quick decisions; the typed
      //     note (if any) is NOT sent to the agent.  Approve/Reject
      //     are also disabled in the template while a message is
      //     drafted, so reaching here on those actions normally
      //     implies an empty draft anyway — the gate here is the
      //     belt-and-suspenders backstop that keeps the audit trail
      //     honest if the disable wiring ever drifts.
      //   * comment — the explicit "Send" path that routes the
      //     typed message to the agent as a redirect.
      const sendNote = action === 'comment' && !!this.resolutionNote;
      this.$emit('act', {
        id: this.item.id,
        action,
        payload: sendNote ? { resolution_notes: this.resolutionNote } : undefined,
      });
    },

    doDismiss() {
      this.acting = true;
      this.$emit('dismiss', this.item.id);
    },

    formatTime(isoDate: string): string {
      return formatRelativeTime(isoDate, this.$t);
    },
  },
});
</script>

